// The C source defines __SYSCALL_COMPAT and includes the architecture and
// generic syscall declarations.  Those generated declarations are supplied
// by the surrounding build.

// __SYSCALL_WITH_COMPAT(nr, native, compat) expands to __SYSCALL(nr, compat).

// The following declarations are generated by asm/syscall_table_32.h in the
// C source.  Keep the generated dependency external rather than inventing
// implementations here.
extern "C" {
    pub fn __riscv_sys_ni_syscall(regs: *const pt_regs) -> isize;
    pub fn compat_sys_rt_sigreturn();
}

#[repr(C)]
pub struct pt_regs {
    _private: [u8; 0],
}

// Generated syscall declarations corresponding to:
// #define __SYSCALL(nr, call) asmlinkage long __riscv_##call(const struct pt_regs *);
// #include <asm/syscall_table_32.h>

// Generated table entries corresponding to:
// #define __SYSCALL(nr, call) [nr] = __riscv_##call,
// #include <asm/syscall_table_32.h>
//
// __NR_syscalls is provided by the architecture syscall definitions.
extern "C" {
    pub static __NR_syscalls: usize;
}

#[allow(non_upper_case_globals)]
pub static compat_sys_call_table: [*const core::ffi::c_void; __NR_syscalls] = {
    // [0 ... __NR_syscalls - 1] = __riscv_sys_ni_syscall,
    // The generated asm/syscall_table_32.h entries follow this initializer.
    [__riscv_sys_ni_syscall as *const core::ffi::c_void; __NR_syscalls]
};

